/* ===== RESET & BASE ===== */
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-light: #6B6560;
  --border: #E0DBD3;
  --terracotta: #C4725A;
  --sage: #8B9E7E;
  --sand: #D4C5A9;
  --sand-light: #E8E2D6;
  --cream-dark: #EDE8E0;
  --serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img { display: block; max-width: 100%; }

/* ===== TYPOGRAPHY ===== */
h1, h2, h3 {
  font-family: var(--serif);
  font-weight: 700;
  line-height: 1.1;
}

/* ===== NAVIGATION ===== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 100;
  padding: 24px 40px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg);
  transition: padding 0.3s ease;
}

.nav-logo {
  font-family: var(--serif);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  gap: 36px;
  list-style: none;
}

.nav-links a {
  font-size: 0.875rem;
  font-weight: 400;
  letter-spacing: 0.02em;
  color: var(--text-light);
  transition: color 0.2s ease;
  position: relative;
}

.nav-links a:hover {
  color: var(--text);
}

.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width 0.3s ease;
}

.nav-links a:hover::after {
  width: 100%;
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 44px;
  height: 44px;
  cursor: pointer;
  background: none;
  border: none;
  z-index: 110;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--text);
  transition: all 0.3s ease;
  position: absolute;
}

.hamburger span:nth-child(1) { transform: translateY(-7px); }
.hamburger span:nth-child(2) { transform: translateY(0); }
.hamburger span:nth-child(3) { transform: translateY(7px); }

.hamburger.active span:nth-child(1) { transform: rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: rotate(-45deg); }

/* Mobile overlay */
.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 105;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 32px;
  opacity: 0;
  transition: opacity 0.4s ease;
}

.mobile-menu.open {
  display: flex;
  opacity: 1;
}

.mobile-menu a {
  font-family: var(--serif);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--text);
  transition: color 0.2s ease;
}

.mobile-menu a:hover {
  color: var(--terracotta);
}

/* ===== HERO ===== */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 0 40px 80px;
  padding-top: 120px;
}

.hero-title {
  font-size: clamp(2.5rem, 6vw, 5rem);
  max-width: 900px;
  margin-bottom: 0;
  letter-spacing: -0.03em;
}

/* ===== MEDIA SHOWCASE ===== */
.media-showcase {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px;
  padding: 80px 40px;
}

.media-block {
  aspect-ratio: 3 / 4;
  border-radius: 4px;
  overflow: hidden;
}

.media-block:nth-child(1) { background-color: var(--terracotta); }
.media-block:nth-child(2) { background-color: var(--sage); }
.media-block:nth-child(3) { background-color: var(--sand); }

/* ===== CLIENT MARQUEE ===== */
.marquee-section {
  padding: 80px 0;
  overflow: hidden;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.marquee-row {
  display: flex;
  width: max-content;
  margin-bottom: 16px;
}

.marquee-row:last-child {
  margin-bottom: 0;
}

.marquee-track {
  display: flex;
  align-items: center;
  animation: marquee-left 30s linear infinite;
}

.marquee-row:nth-child(2) .marquee-track {
  animation: marquee-right 35s linear infinite;
}

.marquee-row:nth-child(3) .marquee-track {
  animation: marquee-left 28s linear infinite;
}

.marquee-item {
  font-family: var(--serif);
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  font-weight: 700;
  white-space: nowrap;
  padding: 0 24px;
  color: var(--text-light);
  letter-spacing: -0.01em;
}

.marquee-separator {
  color: var(--sand);
  font-size: 0.6em;
  padding: 0 4px;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* ===== ABOUT SECTION ===== */
.about-section {
  padding: 120px 40px;
  max-width: 1400px;
  margin: 0 auto;
}

.about-label {
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-light);
  margin-bottom: 48px;
}

.about-text {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
}

.about-text p {
  font-size: 1.125rem;
  line-height: 1.75;
  color: var(--text);
}

/* ===== FOUNDER LETTER ===== */
.founder-page {
  min-height: 100vh;
  padding: 140px 40px 120px;
}

.founder-label {
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-light);
  margin-bottom: 48px;
  max-width: 640px;
  margin-left: auto;
  margin-right: auto;
}

.founder-letter {
  max-width: 640px;
  margin: 0 auto;
}

.founder-letter h1 {
  font-size: clamp(2rem, 4vw, 3.5rem);
  margin-bottom: 48px;
  letter-spacing: -0.03em;
}

.founder-letter p {
  font-size: 1.125rem;
  line-height: 1.85;
  margin-bottom: 28px;
  color: var(--text);
}

.founder-letter p:last-child {
  margin-bottom: 0;
}

.founder-letter .blammo {
  font-family: var(--serif);
  font-weight: 700;
  color: var(--terracotta);
}

/* ===== SERVICES PAGE ===== */
.services-page {
  min-height: 100vh;
  padding: 140px 40px 120px;
}

.philosophy-section {
  max-width: 900px;
  margin: 0 auto 120px;
  text-align: center;
}

.philosophy-label {
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-light);
  margin-bottom: 32px;
}

.philosophy-heading {
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  margin-bottom: 40px;
  letter-spacing: -0.03em;
}

.philosophy-text {
  font-size: 1.125rem;
  line-height: 1.85;
  color: var(--text);
  max-width: 700px;
  margin: 0 auto;
  text-align: left;
}

/* Divider */
.section-divider {
  width: 60px;
  height: 1px;
  background: var(--border);
  margin: 0 auto 120px;
}

/* Service details */
.service-details {
  max-width: 1100px;
  margin: 0 auto;
}

.service-question {
  font-family: var(--serif);
  font-size: clamp(1.75rem, 3.5vw, 3rem);
  text-align: center;
  margin-bottom: 80px;
  letter-spacing: -0.02em;
}

.service-item {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 48px;
  margin-bottom: 64px;
  padding-bottom: 64px;
  border-bottom: 1px solid var(--border);
}

.service-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
  padding-bottom: 0;
}

.service-name {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.service-name .dot {
  color: var(--terracotta);
}

.service-desc {
  font-size: 1.0625rem;
  line-height: 1.8;
  color: var(--text);
}

/* ===== CLIENTS PAGE ===== */
.clients-page {
  min-height: 100vh;
  padding: 140px 40px 120px;
}

.clients-heading {
  max-width: 900px;
  margin: 0 auto 80px;
}

.clients-heading h1 {
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}

.clients-heading p {
  font-size: 1.125rem;
  color: var(--text-light);
}

.clients-grid {
  max-width: 1100px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 48px 40px;
}

.client-card h3 {
  font-family: var(--serif);
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 12px;
  letter-spacing: -0.01em;
}

.client-card p {
  font-size: 0.9375rem;
  line-height: 1.65;
  color: var(--text-light);
}

/* ===== CONTACT PAGE ===== */
.contact-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 140px 40px 120px;
}

.contact-hero {
  margin-bottom: 80px;
}

.contact-hero h1 {
  font-size: clamp(5rem, 18vw, 14rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 0.85;
}

.contact-links {
  display: flex;
  gap: 48px;
  list-style: none;
}

.contact-links a {
  font-size: 1.125rem;
  font-weight: 400;
  color: var(--text);
  position: relative;
  transition: color 0.2s ease;
}

.contact-links a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 100%;
  height: 1px;
  background: var(--text);
  transform: scaleX(1);
  transform-origin: right;
  transition: transform 0.3s ease, color 0.2s ease;
}

.contact-links a:hover::after {
  transform: scaleX(0);
  transform-origin: left;
}

.contact-links a:hover {
  color: var(--terracotta);
}

/* ===== FOOTER ===== */
.footer {
  padding: 40px;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
  color: var(--text-light);
}

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
  .nav {
    padding: 20px 24px;
  }

  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    padding: 0 24px 60px;
    padding-top: 120px;
  }

  .media-showcase {
    grid-template-columns: 1fr;
    gap: 12px;
    padding: 40px 24px;
  }

  .media-block {
    aspect-ratio: 4 / 3;
  }

  .about-section {
    padding: 80px 24px;
  }

  .about-text {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .founder-page {
    padding: 120px 24px 80px;
  }

  .founder-letter p {
    font-size: 1.0625rem;
    line-height: 1.8;
  }

  .services-page {
    padding: 120px 24px 80px;
  }

  .philosophy-section {
    margin-bottom: 80px;
  }

  .service-item {
    grid-template-columns: 1fr;
    gap: 16px;
    margin-bottom: 48px;
    padding-bottom: 48px;
  }

  .section-divider {
    margin-bottom: 80px;
  }

  .clients-page {
    padding: 120px 24px 80px;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 36px;
  }

  .contact-hero h1 {
    font-size: clamp(3.5rem, 20vw, 8rem);
  }

  .contact-links {
    flex-direction: column;
    gap: 24px;
  }

  .footer {
    padding: 24px;
    flex-direction: column;
    gap: 8px;
    text-align: center;
  }

  .marquee-item {
    font-size: 1.25rem;
  }
}

@media (min-width: 769px) and (max-width: 1024px) {
  .clients-grid {
    grid-template-columns: 1fr 1fr;
  }
}

