  .media-showcase {
    grid-template-columns: 1fr;
    gap: 12px;
    padding: 40px 24px;
  }

  .media-block {
    aspect-ratio: 4 / 3;
  }

  .about-section {
    padding: 80px 24px;
  }

  .about-text {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .founder-page {
    padding: 120px 24px 80px;
  }

  .founder-letter p {
    font-size: 1.0625rem;
    line-height: 1.8;
  }

  .services-page {
    padding: 120px 24px 80px;
  }

  .philosophy-section {
    margin-bottom: 80px;
  }

  .service-item {
    grid-template-columns: 1fr;
    gap: 16px;
    margin-bottom: 48px;
    padding-bottom: 48px;
  }

  .section-divider {
    margin-bottom: 80px;
  }

  .clients-page {
    padding: 120px 24px 80px;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 36px;
  }

  .contact-hero h1 {
    font-size: clamp(3.5rem, 20vw, 8rem);
  }

  .contact-links {
    flex-direction: column;
    gap: 24px;
  }

  .footer {
    padding: 24px;
    flex-direction: column;
    gap: 8px;
    text-align: center;
  }

  .marquee-item {
    font-size: 1.25rem;
  }
}

@media (min-width: 769px) and (max-width: 1024px) {
  .clients-grid {
    grid-template-columns: 1fr 1fr;
  }
}
